@group(0) @binding(0) var input_texture : texture_2d<f32>;
@group(0) @binding(1) var input_sampler : sampler;
struct Params { time: f32, frost_intensity: f32, chromatic_aberration: f32 }
@group(0) @binding(2) var<uniform> params : Params;
struct FragInput { @builtin(position) pos: vec4f, @location(0) uv: vec2f }
fn rand2(p: vec2f) -> vec2f {
    let k = vec2f(127.1, 311.7);
    let s = sin(dot(p, k)) * 43758.5453;
    return fract(vec2f(s, s * 1.3)) * 2.0 - 1.0;
}
@fragment
fn fs_main(in: FragInput) -> @location(0) vec4f {
    let jitter = rand2(floor(in.uv * 80.0) / 80.0) * params.frost_intensity * 0.018;
    let uv_f   = in.uv + jitter;
    let offset = vec2f(params.chromatic_aberration * 0.012, 0.0);
    let r = textureSampleLevel(input_texture, input_sampler, uv_f + offset, 0.0).r;
    let g = textureSampleLevel(input_texture, input_sampler, uv_f,          0.0).g;
    let b = textureSampleLevel(input_texture, input_sampler, uv_f - offset, 0.0).b;
    return vec4f(r, g, b, 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D u_input_texture;
uniform float u_time;
uniform float u_grain_strength;
uniform float u_vignette_size;
in vec2 v_uv;
out vec4 frag_color;
float rand(vec2 co, float seed) {
    return fract(sin(dot(co, vec2(12.9898 + seed, 78.233))) * 43758.5453);
}
void main() {
    vec4  color    = texture(u_input_texture, v_uv);
    float r = dot(color.rgb, vec3(0.393, 0.769, 0.189));
    float g = dot(color.rgb, vec3(0.349, 0.686, 0.168));
    float b = dot(color.rgb, vec3(0.272, 0.534, 0.131));
    vec3  sepia = clamp(vec3(r, g, b), 0.0, 1.0);
    float grain = rand(v_uv, floor(u_time * 24.0)) * 2.0 - 1.0;
    sepia += grain * u_grain_strength * 0.08;
    float dist     = length(v_uv - vec2(0.5));
    float vignette = smoothstep(u_vignette_size, u_vignette_size - 0.25, dist);
    frag_color = vec4(sepia * vignette, color.a);
}

@group(0) @binding(0) var input_texture : texture_2d<f32>;
@group(0) @binding(1) var input_sampler : sampler;
struct Params { time: f32, glitch_amount: f32, tear_frequency: f32 }
@group(0) @binding(2) var<uniform> params : Params;
struct FragInput { @builtin(position) pos: vec4f, @location(0) uv: vec2f }
fn hash(n: f32) -> f32 { return fract(sin(n) * 43758.5453); }
@fragment
fn fs_main(in: FragInput) -> @location(0) vec4f {
    var uv    = in.uv;
    let row   = floor(uv.y * params.tear_frequency);
    let seed  = hash(row + floor(params.time * 8.0) * 0.1);
    let shift = (seed - 0.5) * params.glitch_amount * 0.12;
    if (seed > 0.85) { uv.x = fract(uv.x + shift); }
    let split = params.glitch_amount * 0.008;
    let r = textureSampleLevel(input_texture, input_sampler, uv + vec2f( split, 0.0), 0.0).r;
    let g = textureSampleLevel(input_texture, input_sampler, uv,                       0.0).g;
    let b = textureSampleLevel(input_texture, input_sampler, uv - vec2f( split, 0.0), 0.0).b;
    return vec4f(r, g, b, 1.0);
}

